"use strict";
let shop3dDispose=null;
const shop3dHeldBase=shopHandsetMarkup;
shopHandsetMarkup=function(){const h=shop3dHeldBase();return shopHandset==='black'&&!shopBooting?h.replace('</section>','<button data-shop-3d>拿在手里转一转 / 3D检视</button></section>'):h;};
async function openShop3d(){shop3dDispose?.();dialog('N73 / 立体检视',`<section class="shop3d"><div id="shop3d-stage" role="img" aria-label="可拖动旋转的N73三维机身"><p role="status">正在取出手机……</p></div><p>拖动旋转，双指或按钮缩放。可以转到背面滑开镜头盖。</p><nav><button data-3d-action="front">正面</button><button data-3d-action="back">背面</button><button data-3d-action="cover">滑开 / 合上镜头盖</button><button data-3d-action="plus">放大</button><button data-3d-action="minus">缩小</button><button data-3d-action="return">回到手持 / 开机</button></nav><small>Three.js 程序建模检视；手机系统继续使用原来的可操作界面。</small></section>`);const stage=document.querySelector('#shop3d-stage');let renderer;try{const T=await import('./vendor/three/three.module.js');if(!stage.isConnected)return;const scene=new T.Scene();scene.background=new T.Color('#17221f');const camera=new T.PerspectiveCamera(35,1,.1,100);camera.position.set(0,0,8.5);renderer=new T.WebGLRenderer({antialias:true,alpha:false});renderer.setPixelRatio(Math.min(window.devicePixelRatio||1,1.5));stage.innerHTML='';stage.appendChild(renderer.domElement);renderer.domElement.setAttribute('aria-label','N73 3D检视画布');const phone=new T.Group();scene.add(phone);phone.rotation.set(-.12,.25,0);scene.add(new T.HemisphereLight(0xe9f0ec,0x344a43,2.8));const light=new T.DirectionalLight(0xffffff,4);light.position.set(3,4,5);scene.add(light);const rim=new T.DirectionalLight(0x9bc5e2,3);rim.position.set(-4,1,-3);scene.add(rim);
const mat=(c,m=.2)=>new T.MeshStandardMaterial({color:c,metalness:m,roughness:.38});const metal=mat('#a6adb0',.8),black=mat('#252b30',.3),key=mat('#41494f',.45);
function box(w,h,d,x,y,z,material){const r=Math.min(w,h)*.12,s=new T.Shape();s.moveTo(-w/2+r,-h/2);s.lineTo(w/2-r,-h/2);s.quadraticCurveTo(w/2,-h/2,w/2,-h/2+r);s.lineTo(w/2,h/2-r);s.quadraticCurveTo(w/2,h/2,w/2-r,h/2);s.lineTo(-w/2+r,h/2);s.quadraticCurveTo(-w/2,h/2,-w/2,h/2-r);s.lineTo(-w/2,-h/2+r);s.quadraticCurveTo(-w/2,-h/2,-w/2+r,-h/2);const g=new T.ExtrudeGeometry(s,{depth:d,bevelEnabled:true,bevelThickness:.025,bevelSize:.025,bevelSegments:3,steps:1});g.translate(0,0,-d/2);const mesh=new T.Mesh(g,material);mesh.position.set(x,y,z);phone.add(mesh);return mesh;}
function label(text,w,h,x,y,z,bg='#333d42',fg='#e7efeb',size=50){const c=document.createElement('canvas');c.width=512;c.height=256;const g=c.getContext('2d');g.fillStyle=bg;g.fillRect(0,0,512,256);g.fillStyle=fg;g.textAlign='center';g.textBaseline='middle';g.font=`${size}px sans-serif`;text.split('|').forEach((t,i,a)=>g.fillText(t,256,128+(i-(a.length-1)/2)*65));const texture=new T.CanvasTexture(c);texture.colorSpace=T.SRGBColorSpace;const mesh=new T.Mesh(new T.PlaneGeometry(w,h),new T.MeshBasicMaterial({map:texture}));mesh.position.set(x,y,z+(z>0?.065:-.045));phone.add(mesh);return mesh;}
box(1.82,4.15,.5,0,0,0,metal);box(1.72,4.03,.18,0,0,.22,black);box(1.7,3.9,.1,0,0,-.27,black);box(1.5,1.98,.03,0,.65,.345,mat('#0a141b'));label('23:41|中国移动|存储卡已插入',1.36,1.75,0,.65,.365,'#a9beb1','#243e40',46);label('NOKIA  Nseries',1.25,.18,-.08,1.82,.35,'#252b30','#d9e0df',44);box(.5,.035,.015,0,1.98,.35,black);
for(const x of [-.56,.56]){box(.43,.15,.06,x,-.52,.36,key);box(.43,.15,.06,x,-.76,.36,key);}box(.27,.29,.1,0,-.64,.4,metal);for(let i=0;i<12;i++){const x=(i%3-1)*.39,y=-1.02-Math.floor(i/3)*.25;box(.34,.19,.06,x,y,.36,key);label(['1','2 ABC','3 DEF','4 GHI','5 JKL','6 MNO','7 PQRS','8 TUV','9 WXYZ','*','0','#'][i],.3,.15,x,y,.4,'#41494f','#ecf1ee',45);}for(const x of [-.74,.74])for(const y of [-1.16,-1.7])box(.14,.38,.05,x,y,.35,key);box(.25,.08,.09,.5,2.08,0,black);box(.1,.55,.12,.94,.55,0,key);
const lens=new T.Mesh(new T.CylinderGeometry(.25,.25,.08,32),metal);lens.rotation.x=Math.PI/2;lens.position.set(0,1,-.38);phone.add(lens);const glass=new T.Mesh(new T.CylinderGeometry(.18,.18,.09,32),mat('#152e48',.6));glass.rotation.x=Math.PI/2;glass.position.set(0,1,-.44);phone.add(glass);const cover=box(1.52,1.1,.09,0,1,-.48,key);let coverOpen=false;const backText=label('NOKIA|3.2 megapixel',1.1,.4,0,-.3,-.34,'#252b30','#a9b6b7',40);backText.rotation.y=Math.PI;const sticker=label('原卡保留|不格式化',.8,.4,0,-1.35,-.34,'#b9b19b','#3d3b34',48);sticker.rotation.y=Math.PI;
function draw(){if(!stage.isConnected)return;const w=stage.clientWidth,h=stage.clientHeight;renderer.setSize(w,h,false);camera.aspect=w/h;camera.updateProjectionMatrix();renderer.render(scene,camera);}const pointers=new Map();let pinch=0;renderer.domElement.style.touchAction='none';renderer.domElement.addEventListener('pointerdown',e=>{pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});renderer.domElement.setPointerCapture(e.pointerId);});renderer.domElement.addEventListener('pointermove',e=>{const prev=pointers.get(e.pointerId);if(!prev)return;const dx=e.clientX-prev.x,dy=e.clientY-prev.y;pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});if(pointers.size===2){const p=[...pointers.values()],d=Math.hypot(p[0].x-p[1].x,p[0].y-p[1].y);if(pinch)camera.position.z=T.MathUtils.clamp(camera.position.z+(pinch-d)*.015,5,12);pinch=d;}else{phone.rotation.y+=dx*.012;phone.rotation.x=T.MathUtils.clamp(phone.rotation.x+dy*.008,-1,1);}draw();});for(const type of ['pointerup','pointercancel'])renderer.domElement.addEventListener(type,e=>{pointers.delete(e.pointerId);pinch=0;});renderer.domElement.addEventListener('wheel',e=>{e.preventDefault();camera.position.z=T.MathUtils.clamp(camera.position.z+e.deltaY*.005,5,12);draw();},{passive:false});const buttons=document.querySelector('.shop3d nav');buttons.addEventListener('click',e=>{const a=e.target.closest('[data-3d-action]')?.dataset.threeAction||e.target.closest('[data-3d-action]')?.getAttribute('data-3d-action');if(a==='front')phone.rotation.set(0,0,0);if(a==='back')phone.rotation.set(0,Math.PI,0);if(a==='cover'){coverOpen=!coverOpen;cover.position.y=coverOpen?.1:1;phone.rotation.set(0,Math.PI,0);}if(a==='plus')camera.position.z=Math.max(5,camera.position.z-.6);if(a==='minus')camera.position.z=Math.min(12,camera.position.z+.6);if(a==='return'){shop3dDispose?.();openShop();return;}draw();});const resize=new ResizeObserver(draw);resize.observe(stage);let disposed=false;shop3dDispose=()=>{if(disposed)return;disposed=true;resize.disconnect();phone.traverse(o=>{o.geometry?.dispose();if(o.material){o.material.map?.dispose();o.material.dispose();}});renderer.dispose();renderer.forceContextLoss();};document.querySelector('#modal').addEventListener('close',shop3dDispose,{once:true});stage.dataset.ready='true';draw();}catch(err){renderer?.dispose();if(stage.isConnected)stage.innerHTML='<p>此浏览器暂时无法开启3D。你仍可回到手持界面继续开机与探索。</p>';}}
document.addEventListener('click',e=>{if(!e.target.closest('[data-shop-3d]'))return;openShop3d();});
